'use strict';
let user=null,model=null,records=[],view='home',activeCode='INT.00',editing=null,filterResults=[],draftDirty=false,templates=[],drafts=[],documents=[],draftEditing=null,documentEditing=null,libraryError='';
const $=id=>document.getElementById(id);
const localMode=DQService.local;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function today(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function niceDate(s){if(!s)return '—';const match=/^(\d{4})-(\d{2})-(\d{2})/.exec(s);return match?`${match[3]}/${match[2]}/${match[1]}`:s}
function toast(msg){let el=$('toast');el.textContent=msg;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3400)}
async function api(url,method='GET',body=null){return DQService.request(url,method,body)}
async function start(){const me=await api('/api/me');user=me.user;$('exportLocal').hidden=$('importLocal').hidden=!localMode||!user||user.role==='lettore'||user.id==='sandbox';if(!user){$('login').hidden=false;$('app').hidden=true;return}model=await api('/api/content');templates=[];drafts=[];documents=[];draftEditing=null;documentEditing=null;await reload();$('app').hidden=false;$('login').hidden=true;$('newNav').hidden=user.role==='lettore';$('adminNav').hidden=user.role!=='admin';$('accountSide').innerHTML=`<div class="account-chip"><span class="avatar">${esc(user.display_name.slice(0,2).toUpperCase())}</span><div><b>${esc(user.display_name)}</b><small>${esc(localMode?(user.id==='sandbox'?'Laboratorio temporaneo':user.role==='lettore'?'Visitatore demo':'Account locale'):user.role==='admin'?'Amministratore':user.role==='lettore'?'Consultazione':'Delegato')}</small></div></div>`;navigate('home')}
async function reload(){records=(await api('/api/records')).records;await reloadLibrary()}
async function reloadLibrary(){try{const result=await Promise.all(['templates','drafts','documents'].map(key=>api('/api/'+key)));if(result.some((r,i)=>!Array.isArray(r[['templates','drafts','documents'][i]])))throw Error('La risposta della raccolta personale non è valida.');[templates,drafts,documents]=result.map((r,i)=>r[['templates','drafts','documents'][i]]);libraryError='';}catch(error){libraryError=error.message;}}
const subs=()=>model.process.subprocesses;
function procName(code){return code==='INT.00'?'Internazionalizzazione':subs().find(s=>s.code===code)?.name||code}
function options(selected='INT.00',all=false){return (all?'<option value="all">Tutti i processi</option>':'')+['INT.00',...subs().map(s=>s.code)].map(c=>`<option value="${c}" ${c===selected?'selected':''}>${c} · ${esc(procName(c))}</option>`).join('')}
const titles={home:'Panoramica',processi:'Processi',memoria:'Memoria e ricerca',nuova:'Nuova attività',monitoraggio:'Monitoraggio',admin:'Amministrazione',wiki:'Wiki e guide',documenti:'Documenti',documento:'Nuovo documento',lavoro:'Bozze e modelli'};
function navigate(next,prepare=()=>{}){if(['nuova','documento'].includes(view)&&draftDirty){if(!confirm('Abbandonare la compilazione? I dati non salvati andranno persi.'))return;draftDirty=false;}prepare();DocumentPreview.clear();authorPreview.clear();if((next==='nuova'&&user.role==='lettore')||(next==='admin'&&user.role!=='admin'))return;view=next;$('currentPage').textContent=titles[next];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===next||(next==='documento'&&b.dataset.view==='documenti')));$('content').innerHTML=({home,processi,memoria,nuova,monitoraggio,admin,wiki,documenti,documento,lavoro})[next]();wire();if(['demo','sandbox'].includes(user.id)&&next!=='home')$('content').insertAdjacentHTML('afterbegin',`<p class="demo-label">${user.id==='sandbox'?'Laboratorio temporaneo · le prove si perdono al ricaricamento':'Demo Paperopoli · dati e documenti interamente fittizi'}</p>`);$('content').scrollIntoView({block:'start',behavior:'instant'});document.querySelector('.sidebar').classList.remove('open')}
function head(tag,title,description,right=''){return `<div class="page-head"><div><p class="overline">${tag}</p><h1>${title}</h1><p>${description}</p></div>${right}</div>`}
function stat(label,value,note){return `<div class="stat-card"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function empty(title,detail){return `<div class="empty"><div class="empty-icon">◎</div><b>${esc(title)}</b><p>${esc(detail)}</p></div>`}
function recordList(list){return list.length?`<div class="rows">${list.map(r=>`<article class="record-card"><div class="record-top"><div><div class="record-title">${esc(r.subject)}</div><div class="record-meta">${niceDate(r.activity_date)} · ${esc(r.code)} · ${esc(r.author)}</div></div><span class="badge ${esc(r.status)}">${r.status==='in_corso'?'In corso':r.status==='conclusa'?'Conclusa':'Aperta'}</span></div>${r.description?`<div class="record-desc">${esc(r.description).slice(0,250)}${r.description.length>250?'…':''}</div>`:''}<div class="record-bottom"><span class="muted">${r.attachments.length} ${r.attachments.length===1?'documento':'documenti'} collegati</span><button class="text-link" data-detail="${r.id}">Apri dettaglio →</button></div></article>`).join('')}</div>`:empty('Ancora nessuna attività','Quando registrerai un’attività la ritroverai qui, con i relativi documenti e aggiornamenti.')}
function home(){const open=records.filter(x=>x.status!=='conclusa').length;return `${head('','Panoramica','',user.role==='lettore'?'':`<button class="btn primary" data-go="nuova">＋ &nbsp;Registra attività</button>`)}${demoBanner()}${drafts.length?`<div class="notice">Hai ${drafts.length} bozze da completare. <button class="text-link" data-go="lavoro">Riprendi il lavoro →</button></div>`:''}<div class="stat-grid">${stat('Schede operative',subs().length,'Processo pilota Internazionalizzazione')}${stat('Attività registrate',records.length,'Archivio interno')}${stat('Attività non concluse',open,'Aperte o in corso')}</div><div class="section-head"><h2>Azioni</h2></div><div class="action-grid"><button class="action-card" data-go="processi"><span class="action-icon">▦</span><span><b>Consulta i processi</b><small>Trova la procedura, i responsabili e i passaggi da seguire.</small></span></button><button class="action-card" data-go="memoria"><span class="action-icon">⌕</span><span><b>Cerca nella memoria</b><small>Recupera attività, annotazioni, esiti e documenti.</small></span></button>${user.role!=='lettore'?'<button class="action-card" data-go="nuova"><span class="action-icon">＋</span><span><b>Registra un’attività</b><small>Salva le informazioni essenziali in pochi passaggi.</small></span></button>':''}<button class="action-card" data-go="monitoraggio"><span class="action-icon">◫</span><span><b>Consulta il monitoraggio</b><small>Visualizza i dati registrati e lo stato delle attività.</small></span></button></div><div class="section-head"><h2>Attività recenti</h2><button class="text-link" data-go="memoria">Vedi tutte →</button></div>${recordList(records.slice(0,4))}`}
function fields(rows,withHelp=false){return `<div class="field-list">${rows.map(([k,v])=>`<div class="field-row"><div class="field-name">${withHelp?helpLabel(k==='Responsabile operative'?'Responsabile operativo':k,DQFieldTopics[k]):esc(k)}</div><div class="field-value">${esc(v)}</div></div>`).join('')}</div>`}
function processi(){const s=subs().find(x=>x.code===activeCode);return `${head('CATALOGO DEI PROCESSI','Processi dipartimentali','Le schede sono consultabili nella struttura contenuta nei documenti di riferimento.')}<div class="page-grid"><section class="panel process-menu"><button class="process-item ${activeCode==='INT.00'?'active':''}" data-process="INT.00"><span class="code">INT.00</span><span>Scheda madre</span></button>${subs().map(x=>`<button class="process-item ${activeCode===x.code?'active':''}" data-process="${x.code}"><span class="code">${x.code}</span><span>${esc(x.name)}</span></button>`).join('')}</section><div><section class="panel process-main"><p class="overline">${esc(activeCode)} · ${s?'SCHEDA OPERATIVA':'SCHEDA GENERALE'}</p><h2>${helpLabel(s?s.name:'Internazionalizzazione',activeCode)}</h2><div class="notice">Contenuti riportati dal documento di processo v0.2. La consultazione non modifica la scheda validata.</div>${s?`${fields(s.fields,true)}<hr class="divider"><div class="section-head"><h2>${helpLabel('Passaggi operativi','operational-steps')}</h2><span class="badge">${s.steps.length} passaggi</span></div><p class="hint">Apri un passaggio per vedere input, responsabile, attività e output.</p><div class="step-list">${s.steps.map((a,i)=>`<details class="step-item"><summary><span class="step-num">${i+1}</span><span>${esc(a[2]||'Passaggio operativo')}</span><span class="chev">⌄</span></summary><div class="step-content">${[['Input',a[0]],['Responsabile',a[1]],['Attività',a[2]],['Output',a[3]]].map(([k,v])=>`<div class="step-info"><b>${k}</b><span>${esc(v)}</span></div>`).join('')}</div></details>`).join('')}</div><hr class="divider"><h2>Evidenze, indicatori e criticità</h2>${fields([['Evidenze documentali',s.final[0]],['Indicatori di monitoraggio',s.final[1]],['Criticità ricorrenti / attenzione',s.final[2]]],true)}`:`${fields(model.process.mother,true)}<hr class="divider"><h2>${helpLabel('Sottoprocessi collegati','subprocesses')}</h2>${subs().map(x=>`<div class="field-row"><div class="field-name">${helpLabel(x.code+' · '+x.name,x.code)}</div><div class="field-value">${esc(x.when)}</div></div>`).join('')}<hr class="divider"><h2>Evidenze, indicatori e criticità generali</h2>${fields([['Evidenze documentali',model.process.general[0]],['Indicatori di monitoraggio',model.process.general[1]],['Criticità ricorrenti',model.process.general[2]]],true)}`}${user.role!=='lettore'?`<div class="actions-end"><button class="btn primary" data-go="nuova">＋ Registra attività collegata</button></div>`:''}</section><div class="soft-panel"><b>Vademecum delle schede</b><p class="muted" style="margin:5px 0 0">Il vademecum e il documento originale sono inclusi nella cartella «documenti» del pacchetto.</p></div></div></div>`}
function memoria(){return `${head('ARCHIVIO CONSULTABILE','Memoria e ricerca','Trova rapidamente quanto è stato registrato, anche dopo molto tempo.')}<section class="panel"><div class="search-bar"><span class="mag">⌕</span><input id="q" aria-label="Cerca" placeholder="Cerca attività, parole chiave, annotazioni, documenti..."></div><div class="filter-row"><div class="field"><label for="filterCode">Processo</label><select id="filterCode">${options('all',true)}</select></div><div class="field"><label for="filterStatus">Stato</label><select id="filterStatus"><option value="all">Tutti gli stati</option><option value="aperta">Aperta</option><option value="in_corso">In corso</option><option value="conclusa">Conclusa</option></select></div><div class="field"><label for="filterFrom">A partire dal</label><input id="filterFrom" type="date"></div></div><div class="record-bottom"><button class="btn primary" id="searchBtn">Cerca nell'archivio</button><button class="btn light" id="csvBtn">Esporta CSV</button></div></section><div class="section-head"><h2>Risultati</h2><span id="count" class="search-count">${records.length} registrazioni</span></div><div id="results">${recordList(records)}</div><div id="details"></div>`}
function selectedSteps(code,selected){let s=subs().find(x=>x.code===code);return '<option value="">Nessun passaggio specifico</option>'+(s?.steps||[]).map((a,i)=>`<option value="${i+1}" ${Number(selected)===i+1?'selected':''}>${i+1}. ${esc(a[2]).slice(0,125)}</option>`).join('')}
function nuova(){const r=draftEditing?.payload||editing;return `${head('COMPILAZIONE GUIDATA',editing?'Aggiorna registrazione':draftEditing?.id?'Riprendi attività in bozza':'Una nuova attività, passo dopo passo','Tre passaggi: scegli il contesto, racconta l’attività e controlla prima di salvare.')}<section class="panel wizard-panel"><ol class="wizard-progress" aria-label="Avanzamento compilazione"><li data-progress="0" aria-current="step"><span>1</span> Collega</li><li data-progress="1"><span>2</span> Racconta</li><li data-progress="2"><span>3</span> Controlla</li></ol>${templatePicker('activity')}<form id="recordForm" class="form-stack" novalidate>
<div data-wizard="0"><h2 tabindex="-1">1. Dove si colloca l’attività?</h2>${eli('Scegli il cassetto giusto. Il processo indica il tipo di lavoro; il passaggio è un segnalibro facoltativo.')}<div class="form-grid"><div class="field"><label for="recordCode">Processo di riferimento *</label><select id="recordCode">${options(r?.code||activeCode)}</select><small id="processHint" class="hint"></small></div><div class="field"><label for="step">Passaggio (facoltativo)</label><select id="step">${selectedSteps(r?.code||activeCode,r?.step)}</select></div></div></div>
<div data-wizard="1" hidden><h2 tabindex="-1">2. Che cosa è successo?</h2>${eli('Dai un titolo alla cartellina, scrivi quando è successo e se hai finito. Nelle note lascia ciò che vorresti ricordare domani.')}<div class="form-stack"><div class="field"><label for="subject">Oggetto *</label><input id="subject" maxlength="250" required placeholder="Es. Paperino: approvato il piano di studio a Topolinia" value="${esc(r?.subject||'')}"><small class="hint">Un titolo concreto: cosa è successo e a chi si riferisce.</small></div><div class="form-grid"><div class="field"><label for="activityDate">Data dell’attività *</label><input id="activityDate" type="date" required value="${esc(r?.activity_date??today())}"></div><div class="field"><label for="status">Stato *</label><select id="status"><option value="aperta">Aperta · da avviare</option><option value="in_corso">In corso · ci stai lavorando</option><option value="conclusa">Conclusa · lavoro terminato</option></select></div></div><div class="field"><label for="description">Annotazioni (facoltative)</label><textarea id="description" maxlength="10000" placeholder="Cosa è successo? Qual è l’esito? Cosa manca e chi farà il prossimo passo?">${esc(r?.description||'')}</textarea><small class="hint">Esempio: Paperina ha verificato la domanda. Manca un certificato: chiederà l’integrazione.</small></div></div></div>
<div data-wizard="2" hidden><h2 tabindex="-1">3. È tutto corretto?</h2>${eli('Rileggi la tua cartellina. Puoi tornare indietro senza perdere ciò che hai scritto. Salva solo quando sei pronto.')}<div id="reviewContent" aria-live="polite"></div><div class="soft-panel">Dopo il salvataggio potrai aggiungere documenti dal dettaglio dell’attività.</div></div>
<p class="error" id="saveErr" role="alert"></p><div class="authoring-tools"><button type="button" class="btn light" id="saveActivityDraft">Salva bozza</button><button type="button" class="text-btn" id="saveActivityTemplate">Salva come modello</button><span class="hint" id="activityDraftStatus" role="status"></span></div><div class="wizard-actions"><button type="button" class="text-btn" id="cancel">Annulla</button><div><button type="button" class="btn light" id="wizardBack" hidden>← Indietro</button><button type="button" class="btn primary" id="wizardNext">Avanti →</button><button type="submit" class="btn primary" id="wizardSave" hidden>Salva attività</button></div></div><p class="hint">* Campi necessari per la registrazione completa. Puoi salvare una bozza in qualsiasi passaggio.</p></form></section>`}
function monitoraggio(){const completed=records.filter(x=>x.status==='conclusa').length,ongoing=records.filter(x=>x.status==='in_corso').length;return `${head('DATI E ATTIVITÀ','Monitoraggio','Una lettura sintetica delle informazioni già registrate nella piattaforma.')}<div class="stat-grid">${stat('Registrazioni',records.length,'Totale presente in archivio')}${stat('Concluse',completed,'In base allo stato registrato')}${stat('In corso',ongoing,'Da seguire')}</div><div class="panel"><h2>Attività per sottoprocesso</h2><div class="table-scroll"><table><thead><tr><th>Processo</th><th>Registrazioni</th><th>Non concluse</th></tr></thead><tbody>${subs().map(s=>{let rows=records.filter(x=>x.code===s.code);return `<tr><td><b>${s.code}</b> · ${esc(s.name)}</td><td>${rows.length}</td><td>${rows.filter(x=>x.status!=='conclusa').length}</td></tr>`}).join('')}</tbody></table></div></div><div class="notice"><b>Nota metodologica.</b> I conteggi riflettono solo i dati presenti nell'applicazione; non sostituiscono indicatori AQ approvati né costituiscono rendicontazione ufficiale. La scheda INT.08 resta il riferimento per il monitoraggio del processo.</div>`}
function admin(){if(user.role!=='admin')return '';return `${head('CONFIGURAZIONE RISERVATA','Amministrazione','Gestisci gli account e le copie di sicurezza della piattaforma.')}<section class="panel"><h2>Backup completo</h2><p>Il backup comprende database, allegati e schede importate. Contiene informazioni riservate: custodiscilo in un luogo protetto.</p><button class="btn primary" id="backup">↓ Scarica backup ZIP</button></section><section class="panel"><h2>Nuovo account</h2><form id="userForm" class="form-stack"><div class="form-grid"><div class="field"><label>Nome utente</label><input id="newU" required pattern="[A-Za-z0-9._-]{3,40}"></div><div class="field"><label>Nome visualizzato</label><input id="newN" required></div><div class="field"><label>Ruolo</label><select id="newRole"><option value="delegato">Delegato (consultazione e registrazione)</option><option value="lettore">Lettore (sola consultazione)</option><option value="admin">Amministratore</option></select></div><div class="field"><label>Password iniziale (almeno 12 caratteri)</label><input id="newPw" type="password" minlength="12" required autocomplete="new-password"></div></div><div><button class="btn primary">Crea account</button><span id="userMsg" class="hint" style="margin-left:12px"></span></div></form></section><section class="panel"><h2>Utenti autorizzati</h2><div id="users"></div></section>`}
function wire(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>{navigate(x.dataset.go,()=>{if(x.dataset.go==='nuova'){editing=null;draftEditing=null;}})});document.querySelectorAll('[data-process]').forEach(x=>x.onclick=()=>{activeCode=x.dataset.process;navigate('processi')});document.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>openDetail(Number(x.dataset.detail)));if(view==='memoria')wireSearch();if(view==='nuova')wireForm();if(view==='admin')wireAdmin();if(view==='wiki')wireWiki();if(view==='documenti')wireDocuments();if(view==='documento')wireDocumentForm();if(view==='lavoro')wireLibrary();wireWorkLinks();enhanceHelp();const lab=$('startSandbox');if(lab)lab.onclick=async()=>{DQService.enterSandbox();await start();document.querySelector('.offline-pill').textContent='Laboratorio · temporaneo';navigate('nuova')}}
function wireSearch(){let apply=async()=>{try{let args=new URLSearchParams({search:$('q').value,code:$('filterCode').value,status:$('filterStatus').value,from:$('filterFrom').value});filterResults=(await api('/api/records?'+args)).records;$('results').innerHTML=recordList(filterResults);$('count').textContent=filterResults.length+' registrazioni';DocumentPreview.clear();$('details').innerHTML='';document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(Number(b.dataset.detail)))}catch(e){toast(e.message)}enhanceHelp()};filterResults=records;$('searchBtn').onclick=apply;$('q').onkeydown=e=>{if(e.key==='Enter')apply()};$('csvBtn').onclick=()=>exportCSV(filterResults);['filterCode','filterStatus','filterFrom'].forEach(id=>$(id).onchange=apply)}
function exportCSV(rows){const cols=['id','code','step','subject','description','status','activity_date','author','created_at','updated_at'];const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';let csv='\ufeff'+cols.join(';')+'\n'+rows.map(r=>cols.map(k=>quote(r[k])).join(';')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='dispac_ricerca_'+today()+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Risultati esportati')}
async function openDetail(id){DocumentPreview.clear();let r=records.find(x=>x.id===id);if(!r)return navigate('memoria');if(view!=='memoria'){navigate('memoria');}const history=(await api('/api/history/'+id)).history;$('details').innerHTML=`<section class="detail-panel" id="recordDetail"><div class="detail-head"><div><p class="overline">DETTAGLIO REGISTRAZIONE · ${esc(r.code)}</p><h2>${esc(r.subject)}</h2><p class="muted">${niceDate(r.activity_date)} · ${esc(r.author)} · ${esc(procName(r.code))}</p></div><span class="badge ${esc(r.status)}">${r.status==='in_corso'?'In corso':r.status==='conclusa'?'Conclusa':'Aperta'}</span></div><h3>Informazioni conservate</h3><div class="info-box">${esc(r.description||'Nessuna annotazione aggiuntiva.')}</div><div class="section-head"><h3>${helpLabel('Documenti collegati','attachments')}</h3><span class="badge">${r.attachments.length}</span></div><div id="documentPreviews"></div>${user.role!=='lettore'?`<div class="soft-panel"><div class="field"><label for="attachFile">Aggiungi un documento (max ${localMode?2:20} MB)</label><input type="file" id="attachFile"></div><div style="margin-top:11px"><button class="btn light small" id="attachBtn">Carica documento</button></div></div><div class="actions-end"><button class="btn primary" id="editBtn">Modifica registrazione</button></div>`:''}<hr class="divider"><h3>${helpLabel('Storico delle modifiche','history')}</h3>${history.map(h=>`<div class="hist-entry"><b>${esc(h.action)}</b> · ${esc(h.author)} · ${niceDate(h.at)}<details><summary>Vedi i dati registrati</summary><pre>${esc(h.snapshot)}</pre></details></div>`).join('')}</section>`;DocumentPreview.mount($('documentPreviews'),r.attachments,{load:id=>DQService.attachment(id),download:id=>api('/api/attachment/'+id).catch(error=>toast(error.message))});$('recordDetail').scrollIntoView({behavior:'smooth',block:'start'});enhanceHelp();if(user.role!=='lettore'){$('editBtn').onclick=()=>{editing=r;navigate('nuova')};$('attachBtn').onclick=async()=>{let file=$('attachFile').files[0];if(!file)return toast('Seleziona un documento');if(file.size>(localMode?2:20)*1024*1024)return toast('Dimensione massima: '+(localMode?2:20)+' MB');$('attachBtn').disabled=true;try{const data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await api('/api/attachment','POST',{record_id:r.id,name:file.name,data});await reload();toast('Documento archiviato');await openDetail(r.id)}catch(e){toast(e.message)}finally{let b=$('attachBtn');if(b)b.disabled=false}}}}
function wireForm(){let saving=false;const r=editing;const source=draftEditing?.payload||r;let resumedId=draftEditing?.id||null;let current=0;const initialPhase=draftEditing?.phase||0;draftDirty=false;
 const form=$('recordForm');const changed=()=>{draftDirty=true;$('saveErr').textContent='';$('activityDraftStatus').textContent='Modifiche non salvate';};form.addEventListener('input',changed);form.addEventListener('change',changed);
 const hint=()=>{$('processHint').textContent=procName($('recordCode').value)};hint();
 $('recordCode').onchange=e=>{$('step').innerHTML=selectedSteps(e.target.value,null);hint()};$('status').value=source?.status||'aperta';
 const valid=()=>{for(const el of document.querySelectorAll('[data-wizard="1"] input, [data-wizard="1"] textarea')){if(el.id==='subject')el.setCustomValidity(el.value.trim()?'':'Scrivi un oggetto per riconoscere questa attività.');if(!el.reportValidity())return false;}return true};
 const show=index=>{current=index;document.querySelectorAll('[data-wizard]').forEach(el=>el.hidden=Number(el.dataset.wizard)!==index);document.querySelectorAll('[data-progress]').forEach(el=>{el.classList.toggle('done',Number(el.dataset.progress)<index);if(Number(el.dataset.progress)===index)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('wizardBack').hidden=index===0;$('wizardNext').hidden=index===2;$('wizardSave').hidden=index!==2;$('saveErr').textContent='';if(index===2)$('reviewContent').innerHTML=fields([['Processo',$('recordCode').selectedOptions[0].textContent],['Passaggio',$('step').selectedOptions[0].textContent],['Oggetto',$('subject').value.trim()],['Data',niceDate($('activityDate').value)],['Stato',$('status').selectedOptions[0].textContent],['Annotazioni',$('description').value.trim()||'Nessuna annotazione']]);document.querySelector('[data-wizard="'+index+'"] h2').focus()};
 $('subject').oninput=()=>{$('subject').setCustomValidity('')};
 $('wizardNext').onclick=()=>{if(current===1&&!valid())return;show(current+1)};$('wizardBack').onclick=()=>show(current-1);
 const cancel=()=>navigate('memoria',()=>{editing=null;draftEditing=null;});$('cancel').onclick=cancel;
 form.onsubmit=async e=>{e.preventDefault();if(current<2){$('wizardNext').click();return}if(!valid()){show(1);valid();return}if(saving)return;saving=true;const btn=$('wizardSave');const unlock=lockAuthoring();btn.disabled=true;$('wizardBack').disabled=true;try{let result=await api('/api/records','POST',{...(r?{id:r.id}:{}),...activityPayload(),...(resumedId?{draft_id:resumedId}:{})});draftDirty=false;editing=null;draftEditing=null;await reload();navigate('memoria');toast(user.id==='sandbox'?'Prova salvata nel laboratorio temporaneo':'Registrazione salvata');await openDetail(result.id)}catch(error){$('saveErr').textContent=error.message}finally{unlock();saving=false;btn.disabled=false;$('wizardBack')&&($('wizardBack').disabled=false)}}
 const draftStatus=$('activityDraftStatus');
 $('saveActivityDraft').onclick=async()=>{if(saving)return;saving=true;$('saveErr').textContent='';const button=$('saveActivityDraft');const unlock=lockAuthoring();button.disabled=true;try{const result=await api('/api/drafts','POST',{...(resumedId?{id:resumedId}:{}),kind:'activity',payload:activityPayload(),phase:current,record_id:r?.id??null});resumedId=result.id;draftDirty=false;draftStatus.textContent='Bozza salvata alle '+new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});await reloadLibrary();}catch(error){$('saveErr').textContent=error.message;}finally{unlock();saving=false;button.disabled=false;}};
 $('saveActivityTemplate').onclick=()=>saveNamedTemplate('activity',activityPayload());
 wireTemplatePicker('activity',payload=>{$('recordCode').value=payload.code;$('step').innerHTML=selectedSteps(payload.code,payload.step);$('subject').value=payload.subject;$('description').value=payload.description;$('activityDate').value=today();$('status').value='aperta';hint();show(0);draftDirty=true;$('activityDraftStatus').textContent='Modifiche non salvate';});
 if(initialPhase===2&&(!$('subject').value.trim()||!$('activityDate').value))show(1);else if(initialPhase)show(initialPhase);

}
function wireAdmin(){$('backup').onclick=()=>{api('/api/backup').catch(e=>toast(e.message))};$('userForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/users','POST',{username:$('newU').value,display_name:$('newN').value,role:$('newRole').value,password:$('newPw').value});$('userForm').reset();toast('Account creato');loadUsers()}catch(error){$('userMsg').textContent=error.message}};loadUsers()}
async function loadUsers(){const rows=(await api('/api/users')).users;$('users').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Nome</th><th>Username</th><th>Ruolo</th><th>Stato</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.display_name)}</td><td>${esc(x.username)}</td><td>${esc(x.role)}</td><td>${x.active?'Attivo':'Disattivato'}</td></tr>`).join('')}</tbody></table></div>`}
function authMode(register){
 $('loginPanel').hidden=register;$('registerPanel').hidden=!register;
 for(const [id,selected] of [['loginTab',!register],['registerTab',register]]){$(id).setAttribute('aria-selected',String(selected));$(id).tabIndex=selected?0:-1}
 $('authTitle').textContent=register?'Crea account':'Accedi';
 $('authIntro').textContent='';
 $('loginErr').textContent='';$('authSuccess').textContent='';
}
$('loginTab').onclick=()=>authMode(false);$('registerTab').onclick=()=>authMode(true);
for(const id of ['loginTab','registerTab'])$(id).onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const register=e.key==='End'||(e.key!=='Home'&&id==='loginTab');authMode(register);$(register?'registerTab':'loginTab').focus()}};
document.querySelectorAll('[data-password]').forEach(button=>button.onclick=()=>{const field=$(button.dataset.password),show=field.type==='password';field.type=show?'text':'password';button.textContent=show?'Nascondi':'Mostra';button.setAttribute('aria-label',show?'Nascondi password':'Mostra password');button.setAttribute('aria-pressed',String(show))});
async function submitAuth(event,register){event.preventDefault();$('loginErr').textContent='';$('authSuccess').textContent='';const button=event.target.querySelector('[type=submit]');
 if(register&&$('registerPw').value!==$('registerConfirm').value){$('loginErr').textContent='Le password non coincidono.';$('registerConfirm').focus();return}
 button.disabled=true;button.setAttribute('aria-busy','true');
 try{if(register){await api('/api/register','POST',{display_name:$('registerName').value.trim(),username:$('registerUser').value.trim(),password:$('registerPw').value});const username=$('registerUser').value.trim();$('registerForm').reset();authMode(false);$('loginUser').value=username;$('authSuccess').textContent='Account creato. Ora puoi accedere con le tue credenziali.';$('loginPw').focus()}else{await api('/api/login','POST',{username:$('loginUser').value.trim(),password:$('loginPw').value});await start();$('loginPw').value=''}}catch(error){$('loginErr').textContent=error.message}finally{button.disabled=false;button.removeAttribute('aria-busy')}
}
$('loginForm').onsubmit=e=>submitAuth(e,false);$('registerForm').onsubmit=e=>submitAuth(e,true);
$('authYear').textContent=new Date().getFullYear();$('previewNotice').hidden=!localMode;$('demoAccess').hidden=!localMode;
if(!localMode)document.querySelector('.register-note').textContent='Crea un account sul server della piattaforma.';
document.querySelector('.offline-pill').textContent=localMode?'Dati in questo browser':'Archivio condiviso';
$('demoButton').onclick=async()=>{try{DQService.enterDemo();await start();document.querySelector('.offline-pill').textContent='Demo · sola consultazione'}catch(error){$('loginErr').textContent=error.message}};
$('exportLocal').onclick=()=>{try{DQService.exportArchive();toast('Copia esportata: conservala in un luogo protetto.')}catch(error){toast(error.message)}};
$('importLocal').onclick=()=>$('importFile').click();
$('importFile').onchange=async e=>{const file=e.target.files[0];try{if(!file)return;if(file.size>10*1024*1024)throw Error('Dimensione massima copia: 10 MB.');const text=await file.text();if(!confirm('Importare questa copia? Attività, documenti, bozze e modelli di questo account saranno sostituiti. Esporta prima una copia dei dati attuali.'))return;DQService.importArchive(text);await reload();navigate('home');toast('Archivio importato.')}catch(error){toast(error.message)}finally{e.target.value=''}};
$('logout').onclick=async()=>{if(draftDirty&&!confirm('Uscire senza salvare la compilazione?'))return;draftDirty=false;try{await api('/api/logout','POST',{});location.reload()}catch(error){toast(error.message)}};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view,()=>{editing=null;draftEditing=null;documentEditing=null;}));$('menuToggle').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');start().catch(error=>$('loginErr').textContent=error.message);

function eli(text){return `<aside class="eli-box"><p>${esc(text)}</p></aside>`}
function demoBanner(){return ['demo','sandbox'].includes(user.id)?`<div class="demo-banner"><div><b>${user.id==='sandbox'?'Laboratorio di Paperopoli':'Benvenuto a Paperopoli'}</b><p>${user.id==='sandbox'?'Una copia temporanea degli esempi. Le tue prove si perdono quando esci o ricarichi.':'Nove attività, nove documenti e uno storico da esplorare. Tutto è inventato per imparare.'}</p></div>${user.id==='demo'?'<button class="btn primary" id="startSandbox">Prova la compilazione →</button>':'<button class="btn light" data-go="nuova">Nuova prova →</button>'}</div>`:''}
function articleHTML(a){return `<p class="overline">${esc(a.category)}</p><h2 id="guideTitle">${esc(a.title)}</h2>${eli(a.eli)}<p class="guide-body">${esc(a.body)}</p><h3>Come fare</h3><ol class="guide-steps">${a.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="guide-example"><b>Esempi</b>${[a.example,...(a.examples||[])].map(text=>`<p>${esc(text)}</p>`).join('')}</div>`}
function wiki(){return `${head('IL MANUALE DELLA PIATTAFORMA','Wiki e guide','Dalle prime esplorazioni al salvataggio dei documenti: una guida pratica, con esempi di Paperopoli.')}<div class="wiki-intro">${eli('Non devi imparare tutto prima di iniziare. Cerca un argomento qui, oppure usa il ? accanto a una voce per capire esattamente che cosa significa o come compilarla. Da tastiera usa Tab; su smartphone i punti interrogativi restano visibili.')}</div><div class="wiki-layout"><aside class="panel wiki-index"><label for="wikiSearch">Cerca nella guida</label><input id="wikiSearch" type="search" placeholder="Es. allegati, stato, processo…"><p id="wikiCount" class="hint" role="status"></p><div id="wikiLinks"></div></aside><section id="wikiArticle" class="panel wiki-article">${articleHTML(DQGuide[0])}</section></div>`}
function wireWiki(){let active='inizio';const render=()=>{const q=$('wikiSearch').value.trim().toLocaleLowerCase('it');const list=DQGuide.filter(a=>[a.title,a.category,a.body,a.eli,a.example,...(a.examples||[]),...a.steps].join(' ').toLocaleLowerCase('it').includes(q));$('wikiCount').textContent=list.length+' argomenti';$('wikiLinks').innerHTML=list.length?list.map(a=>`<button type="button" data-article="${a.id}" aria-pressed="${a.id===active}"><small>${esc(a.category)}</small>${esc(a.title)}</button>`).join(''):empty('Nessun argomento','Prova una parola diversa, per esempio “documenti”.');document.querySelectorAll('[data-article]').forEach(b=>b.onclick=()=>{active=b.dataset.article;$('wikiArticle').innerHTML=articleHTML(DQGuide.find(a=>a.id===active));render();$('guideTitle').tabIndex=-1;$('guideTitle').focus()})};$('wikiSearch').oninput=render;render()}
// Help is opt-in: a topic is attached only to a precise label or heading.
function helpButton(id){const a=DQGuide.find(a=>a.id===id);return a?`<button type="button" class="context-help" data-help="${id}" aria-label="Guida: ${esc(a.title)}" title="${esc(a.title)}">?</button>`:''}
function helpLabel(text,id){return `<span class="help-anchor">${esc(text)}${helpButton(id)}</span>`}
function enhanceHelp(){
 const map={recordCode:'code',step:'step',subject:'subject',activityDate:'date',status:'status',description:'description',filterCode:'filter-code',filterStatus:'filter-status',filterFrom:'filter-date'};
 for(const [id,topic] of Object.entries(map)){
  const label=document.querySelector(`label[for="${id}"]`);
  if(label&&!label.querySelector('[data-help]'))label.innerHTML=helpLabel(label.textContent,topic);
 }
 const search=$('q');if(search&&!search.parentElement.querySelector('[data-help]'))search.insertAdjacentHTML('afterend',`<span class="help-anchor">${helpButton('search-text')}</span>`);
}
function openHelp(id,trigger){let dialog=$('helpDrawer');if(!dialog){dialog=document.createElement('dialog');dialog.id='helpDrawer';dialog.className='help-drawer';dialog.setAttribute('aria-labelledby','guideTitle');document.body.append(dialog)}const a=DQGuide.find(a=>a.id===id);if(!a)return;dialog.setAttribute('aria-labelledby','drawerGuideTitle');dialog.innerHTML=`<div class="help-toolbar"><span>WIKI · AIUTO CONTESTUALE</span><button type="button" class="btn light small" id="closeHelp">Chiudi ×</button></div><div class="help-content">${articleHTML(a)}<button type="button" class="btn primary" id="fullWiki">Apri la wiki completa →</button></div>`;dialog.querySelector('#guideTitle').id='drawerGuideTitle';dialog.onclose=()=>{if(trigger?.isConnected)trigger.focus()};$('closeHelp').onclick=()=>dialog.close();$('fullWiki').hidden=!user;$('fullWiki').onclick=()=>{dialog.onclose=null;dialog.close();navigate('wiki');if(view!=='wiki')return;$('wikiSearch').value=a.title;$('wikiSearch').dispatchEvent(new Event('input'));document.querySelector('[data-article="'+a.id+'"]').click()};dialog.onclick=e=>{if(e.target===dialog&&e.clientX<dialog.getBoundingClientRect().left)dialog.close()};dialog.showModal();$('closeHelp').focus()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-help]');if(b){e.preventDefault();e.stopPropagation();openHelp(b.dataset.help,b)}});
$('quickHelp').onclick=()=>navigate('wiki');
enhanceHelp();

window.addEventListener('beforeunload',event=>{if(draftDirty){event.preventDefault();event.returnValue=''}});

DQWorkspace.configure({context:()=>({records,canAttach:!!user&&user.role!=='lettore'}),attach:attachFileToRecord});
document.querySelectorAll('[data-workspace]').forEach(button=>button.onclick=()=>DQWorkspace.open(button));

function activityPayload(){return {code:$('recordCode').value,step:$('step').value?Number($('step').value):null,subject:$('subject').value,activity_date:$('activityDate').value,status:$('status').value,description:$('description').value};}
function docPayload(){return {title:$('docTitle').value,body:$('docText').value,format:$('docFormat').value};}
function templateOptions(kind){const group=(name,list,prefix)=>list.length?`<optgroup label="${name}">${list.map(t=>`<option value="${prefix}${t.id}">${esc(t.name)}</option>`).join('')}</optgroup>`:'';return '<option value="">Scegli un modello…</option>'+group('Modelli iniziali',DQDocuments.starters.filter(t=>t.kind===kind),'starter:')+group('I tuoi modelli',templates.filter(t=>t.kind===kind),'personal:');}
function libraryNotice(){return libraryError?`<p class="error" role="alert">Impossibile caricare la raccolta personale: ${esc(libraryError)} <button type="button" class="text-link" data-retry-library>Riprova</button></p>`:'';}
function templatePicker(kind){return `<div class="template-picker"><div class="field"><label for="templateChoice">${helpLabel('Parti da un modello','personal-templates')}</label><select id="templateChoice">${templateOptions(kind)}</select></div><button type="button" class="btn light" id="applyTemplate">Usa modello</button><p class="hint">I modelli compilano i contenuti. ${kind==='activity'?'Data e stato ripartono da oggi e Aperta. ':''}Completa le parti fra parentesi quadre.</p>${libraryNotice()}</div>`;}
function wireTemplatePicker(kind,apply){$('applyTemplate').onclick=()=>{const value=$('templateChoice').value;if(!value)return toast('Seleziona un modello');if(draftDirty&&!confirm('Sostituire i campi compilati con il modello selezionato?'))return;const [origin,id]=value.split(':');const t=(origin==='starter'?DQDocuments.starters:templates).find(t=>t.id===id&&t.kind===kind);if(!t)return toast('Modello non disponibile');apply(DQDocuments.fill(t.payload,user.display_name,niceDate(today())));};}
function saveNamedTemplate(kind,payload,existing=null){
 let dialog=$('templateDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='templateDialog';dialog.className='template-dialog';document.body.append(dialog);}const trigger=document.activeElement;
 dialog.setAttribute('aria-labelledby','templateDialogTitle');dialog.innerHTML=`<h2 id="templateDialogTitle">${existing?'Rinomina modello':'Salva modello personale'}</h2><p>I modelli conservano il testo riutilizzabile. Allegati, collegamenti a registrazioni e, per le attività, data e stato non vengono copiati.</p><form id="templateNameForm" class="form-stack"><div class="field"><label for="templateName">Nome del modello</label><input id="templateName" required maxlength="100" value="${esc(existing?.name||(payload.title||payload.subject||'').slice(0,100))}"></div><p id="templateErr" class="error" role="alert"></p><div class="form-actions"><button class="btn primary" type="submit">Salva modello</button><button class="btn light" type="button" id="templateCancel">Annulla</button></div></form>`;dialog.onclose=()=>{if(trigger?.isConnected)trigger.focus()};$('templateCancel').onclick=()=>dialog.close();$('templateNameForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('/api/templates','POST',{...(existing?{id:existing.id}:{}),name:$('templateName').value.trim(),kind,payload});await reloadLibrary();if($('templateChoice')){$('templateChoice').innerHTML=templateOptions(kind);}dialog.close();toast('Modello salvato nel tuo account');if(view==='lavoro')navigate('lavoro');}catch(error){$('templateErr').textContent=error.message;}finally{button.disabled=false;}};dialog.showModal();$('templateName').focus();
}
function documenti(){return `${head('DOCUMENTI DI LAVORO','Documenti','Scrivi un documento testuale, riusa un modello e conserva le versioni complete nel tuo archivio.',user.role==='lettore'?'':'<button type="button" class="btn primary" data-new-document>＋ Nuovo documento</button>')}${libraryNotice()}${eli('Un documento contiene un testo da conservare o allegare. Una bozza è ancora da completare; un modello è una base che puoi usare più volte.')}<div class="section-head"><h2>Documenti salvati</h2><button class="text-link" data-go="lavoro">Bozze e modelli →</button></div>${documents.length?`<div class="rows">${documents.map(d=>`<article class="record-card"><div class="record-top"><div><b>${esc(d.payload.title)}</b><p class="record-meta">${niceDate(d.updated_at)} · ${esc(d.author)} · ${esc(d.payload.format.toUpperCase())}</p></div><span class="badge">Completo</span></div><p class="record-desc">${esc(d.payload.body.slice(0,180))}${d.payload.body.length>180?'…':''}</p><div class="form-actions"><button class="btn light small" data-read-document="${d.id}">Leggi</button><button class="btn light small" data-download-document="${d.id}">Scarica ${esc(d.payload.format.toUpperCase())}</button>${user.role==='lettore'?'':`<button class="text-link" data-edit-document="${d.id}">Modifica</button><button class="text-link" data-template-document="${d.id}">Salva come modello</button><button class="text-link" data-attach-document="${d.id}">Allega copia</button>`}</div></article>`).join('')}</div>`:empty('Nessun documento completo','Crea un documento, oppure riprendi una bozza dalla raccolta personale.')}<section id="savedDocumentPreview"></section>`;}
function documento(){if(user.role==='lettore')return empty('Documenti in consultazione','Entra nel laboratorio per provare la scrittura.');const r=draftEditing?.payload||documentEditing?.payload;return `${head('EDITOR TESTUALE',documentEditing?'Modifica documento':'Nuovo documento','Il testo può essere salvato come bozza, riutilizzato come modello ed esportato.')}<section class="panel document-editor">${templatePicker('document')}<form id="documentForm" class="form-stack" novalidate><div class="field"><label for="docTitle">${helpLabel('Titolo del documento','document-title')}</label><input id="docTitle" maxlength="250" value="${esc(r?.title||'')}" placeholder="Es. Verbale della riunione con Paperina"></div><div class="field"><label for="docFormat">${helpLabel('Formato di esportazione','document-format')}</label><select id="docFormat"><option value="txt">TXT · testo semplice</option><option value="rtf">RTF · testo apribile in Word e LibreOffice</option><option value="md">Markdown · testo con marcatori</option></select><small class="hint">L’editor scrive testo. Il formato RTF conserva caratteri, paragrafi e tabulazioni; non aggiunge impaginazione o immagini.</small></div><div class="field"><label for="docText">${helpLabel('Testo del documento','document-body')}</label><textarea id="docText" maxlength="1000000" placeholder="Scrivi il testo o parti da un modello…">${esc(r?.body||'')}</textarea><small id="docLength" class="hint"></small></div><p id="docMessage" role="status" class="hint"></p><p id="docError" role="alert" class="error"></p><div class="form-actions"><button type="submit" class="btn primary">Salva documento completo</button><button type="button" class="btn light" id="saveDocumentDraft">Salva bozza</button><button type="button" class="btn light" id="previewDocument">Anteprima</button><button type="button" class="text-btn" id="saveDocumentTemplate">Salva come modello</button><button type="button" class="text-btn" id="cancelDocument">Chiudi</button></div><p class="hint">Per il documento completo servono titolo e testo. La bozza può essere incompleta e si riprende da Bozze e modelli.</p></form><div id="documentEditorPreview"></div></section>`;}
function lavoro(){const label=d=>d.kind==='activity'?(d.payload.subject.trim()||'Bozza senza oggetto'):(d.payload.title.trim()||'Bozza senza titolo');return `${head('RACCOLTA PERSONALE','Bozze e modelli','Le bozze conservano il lavoro in corso. I modelli conservano contenuti da riutilizzare.')} ${libraryNotice()}<div class="section-head"><h2>${helpLabel('Bozze da completare','saved-drafts')}</h2><span class="badge">${drafts.length}</span></div>${drafts.length?`<div class="rows">${drafts.map(d=>`<article class="record-card"><b>${esc(label(d))}</b><p class="record-meta">${d.kind==='activity'?'Attività · passaggio '+(d.phase+1):'Documento'} · ${niceDate(d.updated_at)} · ${d.record_id||d.document_id?'Modifica di un elemento esistente':'Nuovo elemento'}</p><div class="form-actions"><button class="btn primary small" data-resume-draft="${d.id}">Riprendi bozza</button><button class="text-btn" data-delete-draft="${d.id}">Elimina bozza</button></div></article>`).join('')}</div>`:empty('Nessuna bozza salvata','Durante la compilazione premi Salva bozza, anche se mancano informazioni.')}<div class="section-head"><h2>${helpLabel('I tuoi modelli','personal-templates')}</h2><span class="badge">${templates.length}</span></div>${templates.length?`<div class="rows">${templates.map(t=>`<article class="record-card"><b>${esc(t.name)}</b><p class="record-meta">${t.kind==='activity'?'Attività':'Documento'} · ${niceDate(t.updated_at)}</p><div class="form-actions"><button class="btn light small" data-use-template="${t.id}">Usa modello</button><button class="text-btn" data-rename-template="${t.id}">Rinomina</button><button class="text-btn" data-delete-template="${t.id}">Elimina modello</button></div></article>`).join('')}</div>`:empty('Nessun modello personale','Compila un esempio utile e scegli Salva come modello. I modelli iniziali sono già disponibili nei nuovi documenti.')}<div class="form-actions"><button class="btn light" data-go="nuova">Nuova attività</button><button class="btn light" data-new-document>Nuovo documento</button></div>`;}
const authorPreview=window.createDQDocumentPreview('authorDocumentTitle');
function mountAuthoredDocument(host,payload){authorPreview.clear();host.innerHTML='';const {blob,name}=DQDocuments.makeFile(payload);authorPreview.mount(host,[{id:1,file_name:name,size:blob.size}],{load:async()=>({blob}),download:()=>DQDocuments.download(payload)});}
function wireWorkLinks(){document.querySelectorAll('[data-new-document]').forEach(button=>button.onclick=()=>navigate('documento',()=>{documentEditing=null;draftEditing=null;}));document.querySelectorAll('[data-retry-library]').forEach(button=>button.onclick=async()=>{await reloadLibrary();if(['documenti','lavoro'].includes(view))navigate(view);else {button.parentElement.textContent=libraryError?'Raccolta non disponibile: '+libraryError:'Raccolta aggiornata';if($('templateChoice'))$('templateChoice').innerHTML=templateOptions(view==='nuova'?'activity':'document');}});}
function wireDocuments(){
 document.querySelectorAll('[data-read-document]').forEach(b=>b.onclick=()=>{const d=documents.find(d=>d.id===b.dataset.readDocument);if(d){mountAuthoredDocument($('savedDocumentPreview'),d.payload);$('savedDocumentPreview').scrollIntoView({block:'center',behavior:'smooth'});}});
 document.querySelectorAll('[data-download-document]').forEach(b=>b.onclick=()=>{const d=documents.find(d=>d.id===b.dataset.downloadDocument);if(d)DQDocuments.download(d.payload);});
 document.querySelectorAll('[data-edit-document]').forEach(b=>b.onclick=()=>navigate('documento',()=>{documentEditing=documents.find(d=>d.id===b.dataset.editDocument);draftEditing=null;}));
 document.querySelectorAll('[data-template-document]').forEach(b=>b.onclick=()=>{const d=documents.find(d=>d.id===b.dataset.templateDocument);if(d)saveNamedTemplate('document',d.payload);});
 document.querySelectorAll('[data-attach-document]').forEach(b=>b.onclick=()=>attachAuthoredDocument(documents.find(d=>d.id===b.dataset.attachDocument)));
}
function wireDocumentForm(){if(user.role==='lettore')return;let saving=false;const existing=documentEditing;let resumedId=draftEditing?.id||null;draftDirty=false;$('docFormat').value=(draftEditing?.payload||existing?.payload)?.format||'txt';const count=()=>{$('docLength').textContent=$('docText').value.length.toLocaleString('it-IT')+' caratteri';};count();const changed=()=>{draftDirty=true;count();$('docError').textContent='';$('docMessage').textContent='Modifiche non salvate';};$('documentForm').oninput=changed;$('documentForm').onchange=changed;
 wireTemplatePicker('document',payload=>{$('docTitle').value=payload.title;$('docText').value=payload.body;$('docFormat').value=payload.format;changed();});
 $('saveDocumentTemplate').onclick=()=>saveNamedTemplate('document',docPayload());$('cancelDocument').onclick=()=>navigate('documenti',()=>{documentEditing=null;draftEditing=null;});
 $('previewDocument').onclick=()=>{try{mountAuthoredDocument($('documentEditorPreview'),docPayload());}catch(error){$('docError').textContent=error.message;}};
 const save=async draft=>{if(saving)return;saving=true;const button=draft?$('saveDocumentDraft'):$('documentForm').querySelector('[type=submit]');const unlock=lockAuthoring();button.disabled=true;$('docError').textContent='';try{const result=await api(draft?'/api/drafts':'/api/documents','POST',draft?{...(resumedId?{id:resumedId}:{}),kind:'document',payload:docPayload(),phase:0,document_id:existing?.id??null}:{...(existing?{id:existing.id}:{}),payload:docPayload(),...(resumedId?{draft_id:resumedId}:{})});draftDirty=false;if(draft){resumedId=result.id;$('docMessage').textContent='Bozza salvata alle '+new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});await reloadLibrary();}else{await reloadLibrary();documentEditing=null;draftEditing=null;navigate('documenti');toast('Documento salvato');}}catch(error){$('docError').textContent=error.message;}finally{unlock();saving=false;button.disabled=false;}};
 $('saveDocumentDraft').onclick=()=>save(true);$('documentForm').onsubmit=e=>{e.preventDefault();save(false);};
}
function wireLibrary(){
 document.querySelectorAll('[data-resume-draft]').forEach(b=>b.onclick=()=>{const draft=drafts.find(d=>d.id===b.dataset.resumeDraft);if(!draft)return;navigate(draft.kind==='activity'?'nuova':'documento',()=>{draftEditing=draft;editing=draft.record_id?records.find(r=>r.id===draft.record_id):null;documentEditing=draft.document_id?documents.find(d=>d.id===draft.document_id):null;});});
 document.querySelectorAll('[data-use-template]').forEach(b=>b.onclick=()=>{const template=templates.find(t=>t.id===b.dataset.useTemplate);if(!template)return;navigate(template.kind==='activity'?'nuova':'documento',()=>{editing=null;documentEditing=null;draftEditing={payload:{...DQDocuments.fill(template.payload,user.display_name,niceDate(today())),...(template.kind==='activity'?{activity_date:today(),status:'aperta'}:{})},phase:0};});});
 document.querySelectorAll('[data-rename-template]').forEach(b=>b.onclick=()=>{const t=templates.find(t=>t.id===b.dataset.renameTemplate);if(t)saveNamedTemplate(t.kind,t.payload,t);});
 for(const [selector,key,collection] of [['[data-delete-draft]','deleteDraft','drafts'],['[data-delete-template]','deleteTemplate','templates']])document.querySelectorAll(selector).forEach(b=>b.onclick=async()=>{if(!confirm(collection==='drafts'?'Eliminare questa bozza?':'Eliminare questo modello personale?'))return;b.disabled=true;try{await api('/api/'+collection+'/'+b.dataset[key],'DELETE');await reloadLibrary();navigate('lavoro');toast('Elemento eliminato');}catch(error){toast(error.message);b.disabled=false;}});
}
async function attachFileToRecord(file,recordId){if(!user||user.role==='lettore')throw Error('Accedi con un account che può registrare attività.');if(file.size>(localMode?2:20)*1024*1024)throw Error('Limite per allegato: '+(localMode?2:20)+' MB.');if(!records.some(r=>r.id===recordId))throw Error('Attività non disponibile.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Impossibile leggere il file.'));reader.readAsDataURL(file);});await api('/api/attachment','POST',{record_id:recordId,name:file.name,data});await reload();}
function attachAuthoredDocument(doc){if(!doc)return;if(!records.length)return toast('Registra prima un’attività a cui collegare il documento.');let dialog=$('attachDocumentDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='attachDocumentDialog';dialog.className='template-dialog';document.body.append(dialog);}dialog.setAttribute('aria-labelledby','attachDocTitle');dialog.innerHTML=`<h2 id="attachDocTitle">Allega una copia</h2><p>${esc(doc.payload.title)}</p><form class="form-stack"><label for="attachDocRecord">Attività di destinazione</label><select id="attachDocRecord">${records.map(r=>`<option value="${r.id}">${esc(r.subject)}</option>`).join('')}</select><p class="hint">La copia allegata non cambia se modifichi in seguito il documento.</p><p id="attachDocError" class="error" role="alert"></p><div class="form-actions"><button type="submit" class="btn primary">Allega copia</button><button type="button" class="btn light" id="attachDocCancel">Annulla</button></div></form>`;const trigger=document.activeElement;dialog.onclose=()=>trigger?.isConnected&&trigger.focus();$('attachDocCancel').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const {blob,name}=DQDocuments.makeFile(doc.payload);await attachFileToRecord(new File([blob],name,{type:blob.type}),Number($('attachDocRecord').value));dialog.close();toast('Copia del documento allegata');}catch(error){$('attachDocError').textContent=error.message;}finally{button.disabled=false;}};dialog.showModal();}

function lockAuthoring(){const controls=Array.from(document.querySelectorAll('#app button,#app input,#app select,#app textarea'));const states=controls.map(control=>control.disabled);controls.forEach(control=>control.disabled=true);return ()=>controls.forEach((control,index)=>control.disabled=states[index]);}
